请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-001

=== 用户原始指令 (query.txt) ===
弄个运动记录卡,列一串项目,点一下进入操作,能读天气,累了提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个运动记录卡,列一串项目,点一下进入操作,能读天气,累了提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    },
    "fitness": {
      "items": [
        {
          "name": {
            "type": "string",
            "description": "运动记录项目名称。",
            "sampleValue": "跑步"
          },
          "summary": {
            "type": "string",
            "description": "该运动项目的今日记录摘要。",
            "sampleValue": "3.2 km"
          }
        },
        {
          "name": {
            "type": "string",
            "description": "运动记录项目名称。",
            "sampleValue": "力量"
          },
          "summary": {
            "type": "string",
            "description": "该运动项目的今日记录摘要。",
            "sampleValue": "18 min"
          }
        }
      ],
      "fatigueReminder": {
        "type": "string",
        "description": "运动疲劳时的短提醒文案。",
        "sampleValue": "累了提醒"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入运动操作入口的短动作文案。",
        "sampleValue": "开始"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动/跑步图标，适合用于运动记录卡片的身份识别和项目入口视觉锚点。"
    }
  ]
}

